        3→const { defaultPlan, defaultSchool, addSeasonNumbers, numberPlan, migrateNumber, DEFAULT_HAIR } = use('rules/plan');
        4→const { NUMBERS } = use('rules/data');
        5→
        6→const newSeed = () => (Math.random() * 1e9) >>> 0;
        7→
        8→function fresh(lang) {
        9→  return { v: 2, lang: lang || 'fr', season: 1, galaDone: false, seenIntro: 0, plan: defaultPlan(), school: defaultSchool(), notebook: [], sound: true, seed: newSeed() };
       10→}
       11→
       12→// round 1's save: the running order, the formation and the goûter carry over; costumes per class become costumes per number
       13→function fromRound1(o) {
       14→  const s = fresh(), p = s.plan;
       15→  try {
       16→    if (o.plan) {
       17→      p.start = o.plan.start ?? p.start; p.interval = o.plan.interval ?? p.interval;
       18→      if (Array.isArray(o.plan.order) && o.plan.order.every((id) => NUMBERS[id] || ['accueil', 'entracte', 'final'].includes(id))) p.order = o.plan.order;
       19→      if (Array.isArray(o.plan.formation) && o.plan.formation.length === 8) p.numbers.G1.A = o.plan.formation.map((q) => ({ x: q.x, z: q.z }));
       20→      p.cakeG = o.plan.cakeG ?? p.cakeG; p.bottles = o.plan.bottles ?? p.bottles;
       21→    }
       22→    if (o.school) {
       23→      s.school.name = o.school.name || '';
       24→      const cos = o.school.costumes || {};
       25→      for (const [id, np] of Object.entries(p.numbers)) { const c = cos[NUMBERS[id].cls]; if (c) { np.costume.color = c.color; if (['tutu', 'jupette', 'justaucorps'].includes(c.style)) np.costume.outfit = c.style; } }
       26→      for (const [cls, c] of Object.entries(cos)) { const h = { bun: 'chignon', ponytail: 'queue', braids: 'tresses', bob: 'carre' }[c.hair]; if (h) p.hair[cls] = h; }
       27→    }
       28→    s.lang = o.lang || 'fr';
       29→  } catch (e) { /* a broken old save starts fresh */ }
       30→  return s;
       31→}
       32→
       33→// fill in anything a newer version added, so an older save keeps working; anything unreadable starts fresh
       34→function mend(input) {
       35→  if (!input || input.v !== 2 || !input.plan || !input.school) return fresh(input && input.lang);
       36→  const s = JSON.parse(JSON.stringify(input)), f = fresh(s.lang);
       37→  for (const k of Object.keys(f)) if (s[k] === undefined) s[k] = f[k];
       38→  for (const k of Object.keys(f.plan)) if (s.plan[k] === undefined) s.plan[k] = f.plan[k];
       39→  for (const k of Object.keys(f.school)) if (s.school[k] === undefined) s.school[k] = f.school[k];
       40→  addSeasonNumbers(s.plan, s.season);
       41→  for (const id of Object.keys(s.plan.numbers)) {
       42→    if (!NUMBERS[id]) { delete s.plan.numbers[id]; continue; }
       43→    const np = s.plan.numbers[id];
       44→    s.plan.numbers[id] = np.blocks || np.moves ? migrateNumber(np) : numberPlan(id);
       45→  }
       46→  s.plan.order = s.plan.order.filter((id) => NUMBERS[id] || ['accueil', 'entracte', 'final'].includes(id));
       47→  for (const c of Object.keys(DEFAULT_HAIR)) if (!s.plan.hair[c] && c in s.plan.hair) s.plan.hair[c] = DEFAULT_HAIR[c];
       48→  return s;
       49→}
       50→
       51→// the next season: new classes join, the dice change
       52→function nextSeason(save) {
       53→  const s = JSON.parse(JSON.stringify(save));
       54→  s.season++; s.galaDone = false; s.seed = newSeed();
       55→  addSeasonNumbers(s.plan, s.season);
       56→  return s;
       57→}
       58→
       59→Object.assign(exports, { fresh, fromRound1, mend, nextSeason, newSeed });
