file_path: /private/var/tmp/own023-r3/B-vibe/work/gala/app/scripts/game/dispatch.js
content:         1→// One press → what changes. Every button in the game sends an event on the channel "gala-act" with an `act` (what
        2→// kind of press: "order:up", "tab", "go") and an `arg` (which card, which tab…). The Game page's dispatcher Function
        3→// hands both here with the save, the screen state and the 3D stage, and writes back what this returns:
        4→//   { save, ui, toast } — a new save, a patch for the screen state, a sentence for the toast.
        5→// The 3D stage is told directly (begin a run, turn the camera): it is the one thing here that is not state.
        6→const A = use('game/actions');
        7→const S = use('game/save');
        8→const { simulate } = use('rules/engine');
        9→const { NUMBERS, seasonRules } = use('rules/data');
       10→const { sayText } = use('view/run');
       11→
       12→const UI0 = { screen: 'prep', tab: 'order', pickNum: 'G1', selBlock: {}, selMove: null, selChain: null, allMoves: false, editB: false, pickDancer: null, armed: null, selected: null, pickedRoom: null, shopCat: 'hall', speed: 1, follow: true, introForced: false, confirm: null, renaming: false };
       13→const num = (x) => Number(x);
       14→const split = (s) => { const i = String(s).indexOf(':'); return i < 0 ? [String(s), ''] : [String(s).slice(0, i), String(s).slice(i + 1)]; };
       15→
       16→function tabChange(save, ui, k) {
       17→  const patch = { tab: k, armed: null, confirm: null, renaming: false };
       18→  if (k !== 'build') patch.selected = null;
       19→  if (k === 'build') patch.pickedRoom = 'dr';
       20→  else if (['formation', 'costumes', 'parking'].includes(k) || ui.pickedRoom === 'dr') patch.pickedRoom = null;
       21→  return { ui: patch };
       22→}
       23→
       24→function begin(save, ui, stage, mode, tryId) {
       25→  if (!stage || (mode === 'gala' && save.galaDone)) return {};
       26→  const res = stage.beginRun(mode, tryId);
       27→  if (!res) return {};
       28→  return { ui: { screen: 'run', res, live: { mode, t: 0, done: false, feed: [], tryId: tryId || null }, speed: 1, pickedRoom: null, armed: null, selected: null, confirm: null } };
       29→}
       30→function stop(stage) {
       31→  if (stage) stage.stopRun();
       32→  return { ui: { screen: 'prep', res: null, live: null } };
       33→}
       34→
       35→function dispatch(act, arg, save, ui, w, stage) {
       36→  ui = { ...UI0, ...(ui || {}) };
       37→  const [group, what] = split(act);
       38→  const out = (r) => r || {};
       39→  switch (group) {
       40→    case 'tab': return tabChange(save, ui, String(arg));
       41→    case 'lang': return { save: { ...save, lang: save.lang === 'en' ? 'fr' : 'en' } };
       42→    case 'sound': { const on = save.sound === false; if (on && stage) stage.wake(); return { save: { ...save, sound: on } }; }
       43→    case 'intro': return { ui: { introForced: true } };
       44→    case 'introGo': {
       45→      const r = { save: { ...save, seenIntro: save.season }, ui: { introForced: false } };
       46→      if (save.season === 2) Object.assign(r.ui, tabChange(save, ui, 'parking').ui);
       47→      return r;
       48→    }
       49→    case 'cam': if (stage) stage.camCmd(String(arg)); return {};
       50→    case 'go': {
       51→      const id = String(arg);
       52→      if (id === 'rehearse') return begin(save, ui, stage, 'rehearsal');
       53→      if (id === 'gala') return begin(save, ui, stage, 'gala');
       54→      if (id === 'speed') { const s = ui.speed >= 8 ? 1 : ui.speed * 2; if (stage) stage.setSpeed(s); return { ui: { speed: s } }; }
       55→      if (id === 'follow') { const f = !ui.follow; if (stage) stage.setFollow(f); return { ui: { follow: f } }; }
       56→      if (id === 'skipNum') { if (stage) stage.skipNumber(); return {}; }
       57→      if (id === 'skip') { if (stage) stage.skipToEnd(); return {}; }
       58→      if (id === 'stop' || id === 'back') return stop(stage);
       59→      if (id === 'nextSeason') { stop(stage); return { save: S.nextSeason(save), ui: { ...UI0, screen: 'prep', res: null, live: null } }; }
       60→      return {};
       61→    }
       62→    case 'try': return begin(save, ui, stage, 'try', ui.pickNum && NUMBERS[ui.pickNum] ? ui.pickNum : 'G1');
       63→    // the 3D stage reports
       64→    case 'runDone': {
       65→      const live = arg || ui.live || {};
       66→      const r = { ui: { screen: 'results', live } };
       67→      if (live.mode === 'gala' && ui.res && !save.galaDone) r.save = A.finishGala(save, ui.res).save;
       68→      return r;
       69→    }
       70→    case 'say': return Array.isArray(arg) ? { toast: sayText(arg, w) } : {};
       71→    case 'stageUi': return { ui: arg && typeof arg === 'object' ? arg : {} };
       72→    case 'place': return out(A.build(save, ui, 'place', arg, w));
       73→    case 'key': return out(A.build(save, ui, String(arg), null, w));
       74→    // the tabs
       75→    case 'order': {
       76→      if (what === 'up' || what === 'down') return out(A.moveCard(save, String(arg), what === 'up' ? -1 : 1));
       77→      const [which, d] = split(what); return out(A.orderStep(save, which, num(d)));
       78→    }
       79→    case 'form': {
       80→      if (what === 'renameAsk') return { ui: { renaming: true } };
       81→      if (what === 'renameCancel') return { ui: { renaming: false } };
       82→      if (what === 'delAsk') return { ui: { confirm: 'delBlock' } };
       83→      if (what === 'confirmNo') return { ui: { confirm: null } };
       84→      if (what === 'renameBlock') { const r = out(A.formationAct(save, ui, 'renameBlock', arg, w)); if (r.save) r.ui = { renaming: false }; return r; }
       85→      if (what === 'delBlock') { const r = out(A.formationAct(save, ui, 'delBlock', null, w)); r.ui = { ...(r.ui || {}), confirm: null }; return r; }
       86→      const idx = (prefix) => num(String(arg).split(prefix).pop());
       87→      if (what === 'step') return out(A.formationAct(save, ui, 'step', idx('s'), w));
       88→      if (what === 'chain') return out(A.formationAct(save, ui, 'chain', idx('c'), w));
       89→      if (what === 'pickDancer') return out(A.formationAct(save, ui, 'pickDancer', idx('-'), w));
       90→      if (what === 'stepTool' || what === 'chainTool') return out(A.formationAct(save, ui, what, arg === 'x' ? 'x' : num(arg), w));
       91→      if (what === 'dropDancer') return out(A.formationAct(save, ui, 'dropDancer', { ...arg, index: num(String(arg.id).split('-').pop()) }, w));
       92→      return out(A.formationAct(save, ui, what, arg, w));
       93→    }
       94→    case 'gouter': {
       95→      if (what === 'snack') return out(A.snack(save, String(arg), w));
       96→      const [which, d] = split(what); return out(A.gouterStep(save, which, num(d)));
       97→    }
       98→    case 'cos': return out(A.costume(save, ui, what, String(arg), w));
       99→    case 'build': {
      100→      if (what === 'goLoge') return { ui: { pickedRoom: 'dr' } };
      101→      return out(A.build(save, ui, what, arg, w));
      102→    }
      103→    case 'park': return out(A.parking(save, what, arg, w));
      104→    case 'shop': {
      105→      if (what === 'cat') return { ui: { shopCat: String(arg) } };
      106→      return out(A.shop(save, what, String(arg), w));
      107→    }
      108→    case 'note': {
      109→      if (what === 'resetAsk') return { ui: { confirm: 'reset' } };
      110→      if (what === 'resetNo') return { ui: { confirm: null } };
      111→      if (what === 'resetYes') { stop(stage); return { save: S.fresh(save.lang), ui: { ...UI0 } }; }
      112→      return {};
      113→    }
      114→    default: return {};
      115→  }
      116→}
      117→
      118→// what the stage's sync needs to know is worth a re-sync: anything but the live evening
      119→const syncKey = (save, ui) => JSON.stringify([save, ui && { ...ui, res: null, live: null }]);
      120→
      121→Object.assign(exports, { dispatch, UI0, syncKey, seasonRulesOf: seasonRules, simulate });
