 12→  hairs: { edit: ['fr', 'en', 'price', 'min'], add: ['fr', 'en', 'min'], optional: ['price'] },
 13→  shoes: { edit: ['fr', 'en', 'price'] },
 14→  accs: { edit: ['fr', 'en', 'price', 'themes'], add: ['fr', 'en'], optional: ['price', 'themes'] },
 15→  pieces: { edit: ['fr', 'en', 'price'] },
 16→  snacks: { edit: ['fr', 'en', 'price'] },
 17→  upgrades: { edit: ['fr', 'en', 'price'] },
 18→  numbers: { edit: ['fr', 'en'] },
 19→  start: { edit: ['stars'], one: true },
 20→};
 21→const RANGES = { d: [1, 3], price: [0, 300], min: [1, 15], stars: [0, 9999], a: [0, 2], b: [0, 2], dx: [-1, 1], dz: [-1, 1] };
 22→
 23→// words nobody wants on a child's screen, in French and English; matched on the letters only, accents and look-alike
 24→// digits removed, so "C0NN@RD" and "connard" are the same word. Short ones must stand alone; long ones anywhere.
 25→const ALONE = ['cul', 'con', 'cons', 'conne', 'pd', 'nik', 'nique', 'niquer', 'bite', 'zob', 'tg', 'fdp', 'ass', 'arse', 'tit', 'tits', 'fag', 'cum', 'wank', 'twat', 'nazi', 'sex', 'sexe', 'porn', 'porno', 'crap', 'piss', 'poo', 'caca', 'pipi', 'prout'];
 26→const ANYWHERE = ['merde', 'putain', 'pute', 'salope', 'connard', 'connasse', 'encule', 'enculer', 'batard', 'bordel', 'couille', 'chier', 'nichon', 'branle', 'bouffon', 'abruti', 'debile', 'cretin', 'idiot', 'pouffiasse', 'fuck', 'shit', 'bitch', 'bastard', 'dick', 'cock', 'pussy', 'slut', 'whore', 'cunt', 'asshole', 'bollock', 'bugger', 'wanker', 'stupid', 'dumb', 'hitler', 'drogue', 'cocaine', 'weed', 'beer', 'biere', 'vodka', 'whisky'];
 27→const LOOK_ALIKE = { 0: 'o', 1: 'i', 3: 'e', 4: 'a', 5: 's', 7: 't', 8: 'b', '@': 'a', $: 's', '€': 'e', '!': 'i', '|': 'i' };
 28→function plainLetters(s) {
 29→  return String(s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().split('').map((ch) => LOOK_ALIKE[ch] || ch).join('');
 30→}
 31→function rude(s) {
 32→  const plain = plainLetters(s), joined = plain.replace(/[^a-z]/g, ''), squeezed = joined.replace(/(.)\1+/g, '$1');
 33→  const words = plain.split(/[^a-z]+/).filter(Boolean);
 34→  if (words.some((x) => ALONE.includes(x) || ALONE.includes(x.replace(/(.)\1+/g, '$1')))) return true;
 35→  return ANYWHERE.some((bad) => joined.includes(bad) || squeezed.includes(bad));
 36→}
 37→
 38→// a name: short plain text, letters, digits, spaces and everyday punctuation only — no markup, no links, nothing rude.
 39→// Returns the tidied name, '' for an empty one, or null when it is refused.
 40→const NAME_CHARS = /^[\p{L}\p{N} '’\-.,!?&()«»“”:]*$/u;
 41→function cleanName(s, max) {
 42→  const name = String(s === undefined || s === null ? '' : s).normalize('NFC').replace(/\s+/g, ' ').trim();
 43→  if (!name) return '';
 44→  if (name.length > (max || 30) || !NAME_CHARS.test(name) || rude(name)) return null;
 45→  return name;
 46→}
 47→
 48→// check one change. table, rowId, fields: what the grown-up sent, laid over what they had already saved for that row.
 49→// Returns { ok: true, fields } with only allowed, tidied values, or { ok: false, reason } — the reason is a key of the
 50→// grown-ups' words.
 51→function checkChange(table, rowId, fields) {
 52→  const T = TABLES[table];
 53→  if (!T) return { ok: false, reason: 'badTable' };
 54→  if (!fields || typeof fields !== 'object' || Array.isArray(fields)) return { ok: false, reason: 'badFields' };
 55→  const id = T.one ? 'row' : String(rowId || '');
 56→  const exists = T.one || (KNOWN[table] || []).includes(id);
 57→  if (!exists) {
 58→    if (!T.add) return { ok: false, reason: 'cannotAdd' };
 59→    if (!/^[a-z][a-zA-Z0-9]{2,19}$/.test(id) || ['constructor', 'prototype', 'toString', 'valueOf'].includes(id)) return { ok: false, reason: 'badId' };
 60→  }
 61→  const allowed = exists ? T.edit : [...T.add, ...(T.optional || [])];
 62→  const out = {};
 63→  for (const [k, v] of Object.entries(fields)) {
 64→    if (!allowed.includes(k)) return { ok: false, reason: 'badField' };
 65→    if (k === 'fr' || k === 'en') {
 66→      const name = cleanName(v, 30);
 67→      if (!name) return { ok: false, reason: name === null ? 'nameRefused' : 'nameEmpty' };
 68→      out[k] = name;
 69→    } else if (k === 'icon') {
 70→      if (!KNOWN.icons.includes(v)) return { ok: false, reason: 'badIcon' };
 71→      out[k] = v;
 72→    } else if (k === 'c') {
 73→      if (v !== 4 && v !== 8) return { ok: false, reason: 'badCounts' };
 74→      out[k] = v;
 75→    } else if (k === 'st') {
 76→      const list = String(v).split(' ').filter(Boolean);
 77→      if (!(v === '*' || (list.length && list.every((x) => KNOWN.styles.includes(x))))) return { ok: false, reason: 'badStyle' };
 78→      out[k] = v === '*' ? '*' : list.join(' ');
 79→    } else if (k === 'themes') {
 80→      if (!Array.isArray(v) || v.length > 4 || !v.every((x) => KNOWN.themes.includes(x))) return { ok: false, reason: 'badTheme' };
 81→      out[k] = [...new Set(v)];
 82→    } else {
 83→      const [lo, hi] = RANGES[k];
 84→      if (typeof v !== 'number' || !Number.isInteger(v) || v < lo || v > hi) return { ok: false, reason: `range_${k}` };
 85→      if ((k === 'dx' || k === 'dz') && v === 0) continue;
 86→      out[k] = v;
 87→    }
 88→  }
 89→  if (!exists) for (const k of T.add) if (out[k] === undefined) return { ok: false, reason: 'missing' };
 90→  if (Object.keys(out).length === 0) return { ok: false, reason: 'nothing' };
 91→  return { ok: true, fields: out, isNew: !exists };
 92→}
 93→
 94→// every saved change → the `over` that gala-rules' applyRows takes; changes that fail the check are left out
 95→function toRows(changes) {
 96→  const over = {}, refused = [];
 97→  for (const c of changes || []) {
 98→    let fields = c.fields;
 99→    if (typeof fields === 'string') { try { fields = JSON.parse(fields); } catch (e) { fields = null; } }
100→    const r = checkChange(c.table, c.rowId, fields);
101→    if (!r.ok) { refused.push(`${c.table}/${c.rowId}`); continue; }
102→    if (TABLES[c.table].one) over[c.table] = r.fields;
103→    else (over[c.table] = over[c.table] || {})[c.rowId] = r.fields;
104→  }
105→  return { over, refused };
106→}

