        "functionScript": "// What a grown-up may change, and how far. The same code runs in the cloud function that saves a change (so a child\n// cannot get round it from the page) and in the browser before a change is laid over the game.\nconst KNOWN = {\"moves\":[\"plie\",\"releve\",\"bras\",\"chasseD\",\"chasseG\",\"avance\",\"recule\",\"tourne\",\"saute\",\"reception\",\"clap\",\"vague\",\"descente\",\"remonte\",\"pirouette\",\"arabesque\",\"sautChat\",\"kick\",\"roulade\",\"moonwalk\",\"toprock\",\"grandJete\",\"fouette\",\"freeze\",\"echange\",\"reverence\"],\"outfits\":[\"justaucorps\",\"jupette\",\"tutu\",\"robe\",\"marin\",\"fee\",\"papillon\",\"cygne\",\"lapin\",\"flocon\",\"etoile\",\"flamenco\",\"princesse\",\"street\",\"abeille\",\"disco\"],\"hairs\":[\"chignon\",\"queue\",\"tresses\",\"carre\",\"couettes\",\"laches\",\"macarons\",\"couronne\",\"ruban\",\"afro\"],\"shoes\":[\"demi\",\"pieds\",\"pointes\",\"jazz\",\"baskets\",\"paillettes\",\"claquettes\"],\"accs\":[\"aucun\",\"noeud\",\"tiare\",\"fleurs\",\"ailes\",\"oreilles\",\"casquette\",\"beret\",\"baguette\",\"antennes\"],\"pieces\":[\"miroir\",\"banc\",\"portant\",\"chaise\",\"plante\",\"lampe\",\"tapis\",\"coiffeuse\",\"etagere\",\"pouf\",\"canape\",\"paravent\",\"fontaine\",\"fruits\",\"enceinte\",\"barre\",\"ventilo\",\"doudous\",\"sieste\",\"horloge\"],\"snacks\":[\"rien\",\"bonbons\",\"fruits\",\"barres\",\"tartines\"],\"upgrades\":[\"sieges\",\"confort\",\"buvette\",\"projecteurs\",\"boule\",\"scene\",\"decorForet\",\"decorMer\",\"decorVille\",\"logeXL\",\"placeur\",\"covoit\",\"navette\",\"rangee\"],\"numbers\":[\"P1\",\"P2\",\"M1\",\"M2\",\"G1\",\"G2\",\"A1\",\"A2\",\"F1\"],\"icons\":[\"💃\",\"🕺\",\"🩰\",\"🎀\",\"👑\",\"🌸\",\"🌼\",\"🌙\",\"⭐\",\"🌟\",\"✨\",\"💫\",\"🦋\",\"🐝\",\"🐞\",\"🦄\",\"🐬\",\"🐧\",\"🦊\",\"🐼\",\"🐸\",\"🌈\",\"☀️\",\"❄️\",\"🔥\",\"🍀\",\"🎈\",\"🎉\",\"🎵\",\"🎶\",\"🥁\",\"🎻\",\"🎺\",\"🪄\",\"🧚\",\"🧜\",\"🦢\",\"🕊️\",\"🌊\",\"🌀\",\"🔄\",\"⬆️\",\"⬇️\",\"➡️\",\"⬅️\",\"👏\",\"🙌\",\"🤸\",\"🧘\",\"🦵\",