file_path: /private/var/tmp/own023-r3/B-vibe/work/gala/app/scripts/settings/apply.js
content:         1→// Lays the grown-ups' saved changes over the game's tables, once per visit, before anything reads them.
        2→// Each saved change is checked again here (settings/check.js), so a row that is not allowed never reaches the game.
        3→const { toRows } = use('settings/check');
        4→const { applyRows } = use('rules/data');
        5→
        6→let applied = null;
        7→function applyOnce(changes) {
        8→  if (applied) return applied;
        9→  const plain = (changes || []).map((c) => ({
       10→    table: typeof c.get === 'function' ? c.get('table') : c.table,
       11→    rowId: typeof c.get === 'function' ? c.get('rowId') : c.rowId,
       12→    fields: typeof c.get === 'function' ? c.get('fields') : c.fields,
       13→  }));
       14→  const { over, refused } = toRows(plain);
       15→  try { applyRows(over); } catch (e) { refused.push(String(e.message)); }
       16→  applied = { count: plain.length - refused.length, refused };
       17→  return applied;
       18→}
       19→const isApplied = () => !!applied;
       20→
       21→Object.assign(exports, { applyOnce, isApplied });
