file_path: /private/var/tmp/own023-r3/B-vibe/work/gala/app/scripts/rules/plan.js
content:         1→// GENERATED from gala-rules/src/plan.js by tools/sync-rules.mjs — do not edit here, edit gala-rules and run it again.
        2→// The starting plan and the starting school, and how a season adds its new numbers. Pure: no DOM, no three.js.
        3→const { hm, NUMBERS, CLS, LOGE, seasonRules, START } = use('rules/data');
        4→
        5→const xz = (pts) => pts.map(([x, z]) => ({ x, z }));
        6→// each number's starting formation: every one fits on the stage except the seniors' "Lumière", a line a metre apart
        7→// (the arms of a senior span 1.6 m: the first rehearsal shows their hands touching, as in round 1)
        8→const FORMATIONS = {
        9→  petits: xz([[-2.5, 1], [-0.5, 1], [1.5, 1], [-1.5, 2.5], [0.5, 2.5], [2.5, 2.5]]),
       10→  moyens: xz([[-3.5, 1], [-1.5, 1], [0.5, 1], [2.5, 1], [-2.5, 2.5], [-0.5, 2.5], [1.5, 2.5], [3.5, 2.5], [-3, 4], [3, 4]]),
       11→  grandes: xz([[-3, 1.5], [-1, 1.5], [1, 1.5], [3, 1.5], [-4, 3.5], [-2, 3.5], [2, 3.5], [4, 3.5]]),
       12→  ados: xz([[-3, 1.5], [-1, 1.5], [1, 1.5], [3, 1.5], [-4, 3.5], [-2, 3.5], [2, 3.5], [4, 3.5]]),
       13→  mamans: xz([[-3, 1.5], [0, 1.5], [3, 1.5], [-4.5, 3.5], [-1.5, 3.5], [1.5, 3.5]]),
       14→};
       15→const G1_LINE = xz([[-3.5, 1.5], [-2.5, 1.5], [-1.5, 1.5], [-0.5, 1.5], [0.5, 1.5], [1.5, 1.5], [2.5, 1.5], [3.5, 1.5]]);
       16→// each number's starting phrase and how many times it repeats (one block, chained that many times). All fill their music
       17→// exactly, except "Lumière": 16 × 32 = 512 counts for 480 counts of music, and a pirouette straight off the floor
       18→const ROUTINES = {
       19→  P1: { moves: ['plie', 'bras', 'saute', 'reception', 'tourne', 'plie', 'reverence'], repeats: 9 },
       20→  P2: { moves: ['clap', 'chasseD', 'clap', 'chasseG', 'saute', 'reception'], repeats: 9 },
       21→  M1: { moves: ['bras', 'descente', 'roulade', 'remonte', 'arabesque'], repeats: 12 },
       22→  M2: { moves: ['kick', 'chasseD', 'kick', 'chasseG', 'sautChat', 'reception'], repeats: 12 },
       23→  G1: { moves: ['plie', 'bras', 'arabesque', 'descente', 'pirouette', 'reverence'], repeats: 16 },
       24→  G2: { moves: ['releve', 'pirouette', 'bras', 'chasseD', 'chasseG'], repeats: 15 },
       25→  A1: { moves: ['toprock', 'vague', 'clap', 'moonwalk', 'chasseD'], repeats: 10 },
       26→  A2: { moves: ['toprock', 'descente', 'freeze', 'remonte', 'vague', 'toprock'], repeats: 12 },
       27→  F1: { moves: ['clap', 'chasseD', 'chasseG', 'tourne', 'kick', 'clap'], repeats: 8 },
       28→};
       29→const COSTUMES = {
       30→  P1: { outfit: 'tutu', color: '#ff9ec7', shoes: 'demi', acc: 'noeud' }, P2: { outfit: 'jupette', color: '#ff6f91', shoes: 'demi', acc: 'aucun' },
       31→  M1: { outfit: 'jupette', color: '#7cc6ff', shoes: 'pieds', acc: 'aucun' }, M2: { outfit: 'justaucorps', color: '#4f7cff', shoes: 'demi', acc: 'aucun' },
       32→  G1: { outfit: 'justaucorps', color: '#b48cff', shoes: 'demi', acc: 'aucun' }, G2: { outfit: 'tutu', color: '#ffffff', shoes: 'demi', acc: 'aucun' },
       33→  A1: { outfit: 'street', color: '#c23652', shoes: 'baskets', acc: 'aucun' }, A2: { outfit: 'street', color: '#2b2236', shoes: 'baskets', acc: 'aucun' },
       34→  F1: { outfit: 'jupette', color: '#86d9a6', shoes: 'demi', acc: 'noeud' },
       35→};
       36→const DEFAULT_HAIR = { petits: 'chignon', moyens: 'queue', grandes: 'chignon', ados: 'queue', mamans: 'carre' };
       37→
       38→function numberPlan(id) {
       39→  const cls = NUMBERS[id].cls, A = (id === 'G1' ? G1_LINE : FORMATIONS[cls]).map((p) => ({ ...p }));
       40→  return { A, B: null, ...oneBlock(ROUTINES[id].moves, ROUTINES[id].repeats), costume: { ...COSTUMES[id] } };
       41→}
       42→// a dance as blocks and a chain: round 2's "phrase × repeats" is one block, chained `repeats` times
       43→const oneBlock = (moves, repeats) => ({ blocks: [{ id: 'a', name: 'A', moves: [...moves] }], chain: Array(repeats).fill('a') });
       44→// an older save's number (moves + repeats) becomes one block, chained as many times: the same dance, nothing lost
       45→function migrateNumber(np) {
       46→  if (np.blocks) return np;
       47→  const { moves = [], repeats = 1, ...rest } = np;
       48→  return { ...rest, ...oneBlock(moves, repeats) };
       49→}
       50→
       51→function defaultPlan() {
       52→  const numbers = {};
       53→  for (const id of ['P1', 'P2', 'M1', 'M2', 'G1', 'G2']) numbers[id] = numberPlan(id);
       54→  return {
       55→    start: hm(20, 0), interval: 1500,
       56→    order: ['accueil', 'P1', 'M1', 'G1', 'entracte', 'P2', 'M2', 'G2', 'final'],
       57→    numbers, hair: { petits: 'chignon', moyens: 'queue', grandes: 'chignon' },
       58→    snack: 'rien', cakeG: 1500, bottles: 3, crepes: 0, compotes: 0,
       59→    parking: { width: 2.5, doors: 30 }, backdrop: 'nuit',
       60→  };
       61→}
       62→
       63→function defaultSchool() {
       64→  return {
       65→    name: '', logeCols: LOGE.cols, stars: START.stars, earned: 0, owned: {}, upgrades: {},
       66→    furniture: [
       67→      { id: 'banc', c: 1, r: 4, rot: 0 }, { id: 'portant', c: 6, r: 5, rot: 0 },
       68→      { id: 'miroir', c: 3, r: 0, rot: 0 }, { id: 'miroir', c: 5, r: 0, rot: 0 },
       69→    ],
       70→  };
       71→}
       72→
       73→// a new season brings its new classes: their numbers join the programme just before the interval and the finale
       74→const ARRIVALS = { ados: [['A1', 'entracte'], ['A2', 'final']], mamans: [['F1', 'final']] };
       75→function addSeasonNumbers(plan, season) {
       76→  for (const cls of seasonRules(season).classes) {
       77→    if (!ARRIVALS[cls]) continue;
       78→    if (!plan.hair[cls]) plan.hair[cls] = DEFAULT_HAIR[cls];
       79→    for (const [id, before] of ARRIVALS[cls]) {
       80→      if (plan.numbers[id]) continue;
       81→      plan.numbers[id] = numberPlan(id);
       82→      const k = plan.order.indexOf(before); plan.order.splice(k < 0 ? plan.order.length - 1 : k, 0, id);
       83→    }
       84→  }
       85→  return plan;
       86→}
       87→const classOf = (id) => CLS[NUMBERS[id].cls];
       88→
       89→Object.assign(exports, { DEFAULT_HAIR, numberPlan, oneBlock, migrateNumber, defaultPlan, defaultSchool, addSeasonNumbers, classOf });
