32→  G1: { outfit: 'justaucorps', color: '#b48cff', shoes: 'demi', acc: 'aucun' }, G2: { outfit: 'tutu', color: '#ffffff', shoes: 'demi', acc: 'aucun' },
33→  A1: { outfit: 'street', color: '#c23652', shoes: 'baskets', acc: 'aucun' }, A2: { outfit: 'street', color: '#2b2236', shoes: 'baskets', acc: 'aucun' },
34→  F1: { outfit: 'jupette', color: '#86d9a6', shoes: 'demi', acc: 'noeud' },
35→};
36→const DEFAULT_HAIR = { petits: 'chignon', moyens: 'queue', grandes: 'chignon', ados: 'queue', mamans: 'carre' };
37→
38→function numberPlan(id) {
39→  const cls = NUMBERS[id].cls, A = (id === 'G1' ? G1_LINE : FORMATIONS[cls]).map((p) => ({ ...p }));
