        4→const { RULES, NUMBERS, MOVES, MAX_MOVES, OUTFITS, HAIRS, SHOES, ACCS, PIECES, LOGE, SNACKS, UPGRADES } = use('rules/data');
        5→const { clamp, isOwned, fits, footprint, routineInfo, danceOf, stageOf } = use('rules/engine');
        6→const { pickedNum } = use('view/common');
        7→const { geometry } = use('view/formation');
        8→const { foodPrice } = use('view/prep');
        9→const { cleanName } = use('settings/check');
       10→
       11→const copy = (o) => JSON.parse(JSON.stringify(o));
       12→const MAX_BLOCKS = 8, MAX_CHAIN = 60;
       13→
       14→// buying: a price in stars, kept for good
       15→function buy(save, kind, id, w) {
       16→  const price = kind === 'up' ? UPGRADES[id].price : kind === 'food' ? foodPrice(id) : (({ outfit: OUTFITS, hair: HAIRS, shoes: SHOES, acc: ACCS, piece: PIECES, snack: SNACKS })[kind][id].price || 0);
       17→  const name = kind === 'up' ? w.nm(UPGRADES[id]) : kind === 'food' ? w(`foods_${id}`) : w.nm(({ outfit: OUTFITS, hair: HAIRS, shoes: SHOES, acc: ACCS, piece: PIECES, snack: SNACKS })[kind][id]);
       18→  const sc = save.school;
       19→  if (sc.stars < price) return { ok: false, toast: w('notEnough') };
       20→  sc.stars -= price;
       21→  if (kind === 'up') sc.upgrades[id] = id === 'sieges' ? (sc.upgrades[id] || 0) + 1 : true;
       22→  else sc.owned[`${kind}:${id}`] = true;
       23→  if (kind === 'up' && id === 'logeXL') sc.logeCols = LOGE.colsBig;
       24→  if (kind === 'up' && id.startsWith('decor')) save.plan.backdrop = { decorForet: 'foret', decorMer: 'mer', decorVille: 'ville' }[id];
       25→  return { ok: true, toast: w('bought', name) };
       26→}
       27→
       28→/* ---------------- the programme ---------------- */
       29→function orderStep(save0, which, d) {
       30→  const save = copy(save0), P = save.plan;
       31→  if (which === 'start') P.start = clamp(P.start + d * 300, RULES.startMin, RULES.startMax);
       32→  if (which === 'interval') P.interval = clamp(P.interval + d * 300, RULES.intervalMin, RULES.intervalMax);
       33→  return { save };
       34→}
       35→function moveCard(save0, id, d) {
       36→  const save = copy(save0), o = save.plan.order, i = o.indexOf(id), j = clamp(i + d, 1, o.length - 2);
       37→  if (i < 1 || i === j) return {};
       38→  o.splice(i, 1); o.splice(j, 0, id);
       39→  return { save };
       40→}
       41→
       42→/* ---------------- the formation and the choreography ---------------- */
       43→function formationAct(save0, ui0, act, arg, w) {
       44→  const save = copy(save0), ui = copy(ui0), id = pickedNum(save, ui, 'G1'), N = NUMBERS[id], np = save.plan.numbers[id];
       45→  ui.selBlock = ui.selBlock || {};
       46→  const bid = np.blocks.some((b) => b.id === ui.selBlock[id]) ? ui.selBlock[id] : np.blocks[0].id, blk = np.blocks.find((b) => b.id === bid);
       47→  const free = () => 'abcdefgh'.split('').find((c) => !np.blocks.some((b) => b.id === c));
       48→  const moveIn = (list, k, d) => { const j = clamp(k + d, 0, list.length - 1); if (j !== k) { const [x] = list.splice(k, 1); list.splice(j, 0, x); } return j; };
       49→  switch (act) {
       50→    case 'pickNum': return { ui: { ...ui0, pickNum: arg, pickDancer: null, editB: false, selMove: null, selChain: null } };
       51→    case 'ab': {
       52→      if (arg === 'B' && !np.B) np.B = np.A.map((p) => ({ ...p }));
       53→      return { save, ui: { ...ui0, editB: arg === 'B' } };
       54→    }
       55→    case 'block': return { ui: { ...ui, selBlock: { ...ui.selBlock, [id]: arg }, selMove: null } };
       56→    case 'newBlock': case 'copyBlock': {
       57→      if (np.blocks.length >= MAX_BLOCKS) return { toast: w('maxBlocks') };
       58→      const f = free();
       59→      np.blocks.push(act === 'newBlock' ? { id: f, name: f.toUpperCase(), moves: [] } : { id: f, name: `${blk.name} 2`.slice(0, 24), moves: [...blk.moves] });
       60→      return { save, ui: { ...ui, selBlock: { ...ui.selBlock, [id]: f }, selMove: null } };
       61→    }
       62→    case 'renameBlock': {
       63→      const name = cleanName(arg, 24);
       64→      if (!name) return { toast: w('nameRefused') };
       65→      blk.name = name; return { save };
       66→    }
       67→    case 'delBlock': {
       68→      if (np.blocks.length < 2) return {};
       69→      np.blocks = np.blocks.filter((b) => b !== blk); np.chain = np.chain.filter((x) => x !== bid);
       70→      return { save, ui: { ...ui, selChain: null, selMove: null } };
       71→    }
       72→    case 'step': return { ui: { ...ui0, selMove: ui0.selMove === arg ? null : arg } };
       73→    case 'stepTool': {
       74→      const k = ui.selMove; if (k === null || k === undefined || !blk.moves[k]) return {};
       75→      if (arg === 'x') { blk.moves.splice(k, 1); return { save, ui: { ...ui0, selMove: null } }; }
       76→      return { save, ui: { ...ui0, selMove: moveIn(blk.moves, k, arg) } };
       77→    }
       78→    case 'addMove': {
       79→      if (!MOVES[arg]) return {};
       80→      if (blk.moves.length >= MAX_MOVES) return { toast: w('maxMoves') };
       81→      blk.moves.push(arg);
       82→      if (MOVES[arg].swap && !np.B) np.B = np.A.map((p) => ({ ...p }));
       83→      return { save };
       84→    }
       85→    case 'chain': return { ui: { ...ui0, selChain: ui0.selChain === arg ? null : arg } };
       86→    case 'chainTool': {
       87→      const k = ui.selChain; if (k === null || k === undefined || k >= np.chain.length) return {};
       88→      if (arg === 'x') { np.chain.splice(k, 1); return { save, ui: { ...ui0, selChain: null } }; }
       89→      return { save, ui: { ...ui0, selChain: moveIn(np.chain, k, arg) } };
       90→    }
       91→    case 'addChain': {
       92→      if (np.chain.length >= MAX_CHAIN) return { toast: w('maxChain') };
       93→      np.chain.push(bid); return { save };
       94→    }
       95→    case 'filter': return { ui: { ...ui0, allMoves: arg === 'all' } };
       96→    case 'pickDancer': return { ui: { ...ui0, pickDancer: arg } };
       97→    case 'dropDancer': {
       98→      // arg: { index, left, top } — the dot's new top-left corner on the plan, in pixels
       99→      const g = geometry(stageOf(save.school)), info = routineInfo(danceOf(np).moves, N.style, false);
      100→      const F = ui.editB && info.swaps && np.B ? np.B : np.A, size = 0.6 * g.k;
      101→      const x = (arg.left + size / 2) / g.k - g.W - 0.9, z = g.D + 0.5 - (arg.top + size / 2) / g.k;
      102→      if (!F[arg.index]) return {};
      103→      F[arg.index] = { x: clamp(Math.round(x * 2) / 2, -g.W - 0.5, g.W + 0.5), z: clamp(Math.round(z * 2) / 2, 0, g.D) };
      104→      return { save, ui: { ...ui0, pickDancer: arg.index } };
      105→    }
      106→    default: return {};
      107→  }
      108→}
      109→
      110→/* ---------------- the goûter ---------------- */
      111→function gouterStep(save0, which, d) {
      112→  const save = copy(save0), P = save.plan;
      113→  if (which === 'cake') P.cakeG = clamp(P.cakeG + d * 50, 0, 8000);
      114→  if (which === 'bottles') P.bottles = clamp(P.bottles + d, 0, 20);
      115→  if (which === 'crepes') P.crepes = clamp((P.crepes || 0) + d, 0, 60);
      116→  if (which === 'compotes') P.compotes = clamp((P.compotes || 0) + d, 0, 60);
      117→  return { save };
      118→}
      119→function snack(save0, id, w) {
      120→  if (!SNACKS[id]) return {};
      121→  const save = copy(save0);
      122→  if (!isOwned(save.school, 'snack', id)) { const b = buy(save, 'snack', id, w); if (!b.ok) return { toast: b.toast }; save.plan.snack = id; return { save, toast: b.toast }; }
      123→  save.plan.snack = id; return { save };
      124→}
      125→
      126→/* ---------------- the costumes ---------------- */
      127→function costume(save0, ui, act, arg, w) {
      128→  const save = copy(save0), id = pickedNum(save, ui), cos = save.plan.numbers[id].costume;
      129→  if (act === 'pickNum') return { ui: { ...ui, pickNum: arg } };
      130→  if (act === 'color') { cos.color = arg; return { save }; }
      131→  let toast;
      132→  if (act === 'item') {
      133→    const [kind, k] = String(arg).split(':'), list = { outfit: OUTFITS, shoes: SHOES, acc: ACCS }[kind];
      134→    if (!list || !list[k]) return {};
      135→    if (!isOwned(save.school, kind, k)) { const b = buy(save, kind, k, w); if (!b.ok) return { toast: b.toast }; toast = b.toast; }
      136→    cos[kind === 'outfit' ? 'outfit' : kind === 'shoes' ? 'shoes' : 'acc'] = k;
      137→    return { save, toast };
      138→  }
      139→  if (act === 'hair') {
      140→    const [cls, k] = String(arg).split(':');
      141→    if (!HAIRS[k]) return {};
      142→    if (!isOwned(save.school, 'hair', k)) { const b = buy(save, 'hair', k, w); if (!b.ok) return { toast: b.toast }; toast = b.toast; }
      143→    save.plan.hair[cls] = k;
      144→    return { save, toast };
      145→  }
      146→  return {};
      147→}
      148→
      149→/* ---------------- the dressing room ---------------- */
      150→function build(save0, ui0, act, arg, w) {
      151→  const save = copy(save0), ui = copy(ui0), sc = save.school, cols = sc.logeCols;
      152→  const same = (a, b) => a && b && a.id === b.id && a.c === b.c && a.r === b.r && a.rot === b.rot;
      153→  const selIndex = ui.selected ? sc.furniture.findIndex((f) => same(f, ui.selected)) : -1;
      154→  switch (act) {
      155→    case 'name': {
      156→      const name = cleanName(arg, 40);
      157→      if (name === null) return { toast: w('nameRefused') };
      158→      sc.name = name; return { save };
      159→    }
      160→    case 'piece': {
      161→      if (!PIECES[arg]) return {};
      162→      let toast;
      163→      if (!isOwned(sc, 'piece', arg)) { const b = buy(save, 'piece', arg, w); if (!b.ok) return { toast: b.toast }; toast = b.toast; }
      164→      return { save, toast, ui: { ...ui0, armed: ui0.armed && ui0.armed.id === arg ? null : { id: arg, rot: 0 }, selected: null } };
      165→    }
      166→    case 'rotateArmed': return ui.armed ? { ui: { ...ui0, armed: { ...ui.armed, rot: (ui.armed.rot + 1) % 4 } } } : {};
      167→    case 'cancelArmed': {
      168→      if (ui.armed && ui.armed.was) sc.furniture.push(ui.armed.was);
      169→      return { save, ui: { ...ui0, armed: null } };
      170→    }
      171→    case 'rotateSelected': {
      172→      if (selIndex < 0) return {};
      173→      const f = sc.furniture[selIndex], old = { c: f.c, r: f.r, rot: f.rot };
      174→      f.rot = (f.rot + 1) % 4;
      175→      if (!fits(f, sc.furniture, cols, f)) { const fp = footprint(f); f.c = clamp(f.c, 0, cols - fp.w); f.r = clamp(f.r, 0, LOGE.rows - fp.d); if (!fits(f, sc.furniture, cols, f)) Object.assign(f, old); }
      176→      return { save, ui: { ...ui0, selected: { ...f } } };
      177→    }
      178→    case 'moveSelected': {
      179→      if (selIndex < 0) return {};
      180→      const [f] = sc.furniture.splice(selIndex, 1);
      181→      return { save, ui: { ...ui0, armed: { id: f.id, rot: f.rot, was: f }, selected: null } };
      182→    }
      183→    case 'removeSelected': {
      184→      if (selIndex < 0) return {};
      185→      sc.furniture.splice(selIndex, 1);
      186→      return { save, ui: { ...ui0, selected: null } };
      187→    }
      188→    case 'place': {
      189→      // arg: { id, c, r, rot } — the 3D view says where the ghost stood when she tapped
      190→      if (!ui.armed || !PIECES[arg.id] || !fits(arg, sc.furniture, cols)) return {};
      191→      const f = { id: arg.id, c: arg.c, r: arg.r, rot: arg.rot };
      192→      sc.furniture.push(f);
      193→      return { save, ui: { ...ui0, selected: { ...f }, armed: ui.armed.was ? null : ui.armed } };
      194→    }
      195→    case 'select': return { ui: { ...ui0, selected: arg ? { ...arg } : null } };
      196→    default: return {};
      197→  }
      198→}
      199→
      200→/* ---------------- the car park and the shop ---------------- */
      201→function parking(save0, act, arg, w) {
      202→  const save = copy(save0), P = save.plan;
      203→  if (act === 'width') P.parking.width = Number(arg);
      204→  if (act === 'doors') P.parking.doors = Number(arg);
      205→  if (act === 'up') { if (save.school.upgrades[arg] || !UPGRADES[arg]) return {}; const b = buy(save, 'up', arg, w); return b.ok ? { save, toast: b.toast } : { toast: b.toast }; }
      206→  return { save };
      207→}
      208→function shop(save0, act, arg, w) {
      209→  const save = copy(save0);
      210→  if (act === 'backdrop') { save.plan.backdrop = arg; return { save }; }
      211→  if (act === 'buy') {
      212→    const [kind, id] = String(arg).split('|');
      213→    const b = buy(save, kind, id, w);
      214→    return b.ok ? { save, toast: b.toast } : { toast: b.toast };
      215→  }
      216→  return {};
      217→}
      218→
      219→/* ---------------- the end of a gala ---------------- */
      220→function finishGala(save0, R) {
      221→  const save = copy(save0);
      222→  save.galaDone = true; save.school.stars += R.points; save.school.earned += R.points;
      223→  save.notebook.unshift({ season: save.season, at: new Date().toISOString().slice(0, 10), points: R.points, satisfaction: R.parents.satisfaction, nums: Object.fromEntries(Object.values(R.perf).map((p) => [p.id, p.total])) });
      224→  return { save };
      225→}
      226→
      227→Object.assign(exports, { buy, orderStep, moveCard, formationAct, gouterStep, snack, costume, build, parking, shop, finishGala });
